class Output {
    public static String output(String input) {
        StringBuilder output = new StringBuilder();
        for (char c : input.toCharArray()) {
            if (" \n\r\t".indexOf(c) != -1 && !Character.isWhitespace(c)) {
                output.append(" ").append(Character.toLowerCase(c));
